    (temp - 1200.0) / 4200.0
      + params.fireIntensity * 0.08
      + params.quantumMaterialIonizationDrive * materialSourceTargetFactor
      + params.quantumMaterialConductivityDrive * materialSourceTargetFactor * 0.018
